INSERT INTO firstten_policy_test.class_documents VALUES('a',jsonb_build_object('name','Discovery class A','mode','class','instructions','Published class instructions','accessExpiresAt',statement_timestamp()+interval '30 days','retentionDays',120)),('b',jsonb_build_object('name','Hackathon B','mode','hackathon','instructions','Other class','accessExpiresAt',statement_timestamp()+interval '20 days','retentionDays',60));
GRANT SELECT,INSERT ON firstten_policy_test.class_results TO authenticated;
GRANT SELECT ON firstten_policy_test.class_documents TO authenticated;
