SELECT ok((SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid IN ('public.classes'::regclass,'public.class_members'::regclass,'public.assignments'::regclass,'public.class_project_links'::regclass,'public.class_teams'::regclass,'public.class_guest_principals'::regclass)),'all new class and guest tables enable RLS');
SELECT ok(NOT has_table_privilege('authenticated','public.classes','SELECT,INSERT,UPDATE,DELETE'),'class owner has no direct table bypass');
SELECT ok(NOT has_table_privilege('authenticated','public.class_members','SELECT,INSERT,UPDATE,DELETE'),'students cannot directly enroll or grant roles');
SELECT ok(NOT has_table_privilege('anon','public.class_teams','SELECT,INSERT,UPDATE,DELETE'),'no anonymous team entry or roster');
SELECT ok(NOT has_table_privilege('authenticated','public.class_guest_principals','SELECT,INSERT,UPDATE,DELETE'),'no authenticated guest minting shortcut');
SELECT ok(NOT has_table_privilege('service_role','public.classes','SELECT,INSERT,UPDATE,DELETE'),'no service-role class-table shortcut');
SELECT ok(NOT has_table_privilege('authenticated','firstten_private.class_invitations','SELECT,INSERT,UPDATE,DELETE'),'class token table is private');
SELECT ok(NOT has_function_privilege('authenticated','firstten_private.mutate_class(text,uuid,uuid,bigint,uuid,jsonb)','EXECUTE'),'fixed operation wrappers protect internal mutation helper');
SELECT ok(NOT has_function_privilege('anon','public.accept_class_invitation(text,text)','EXECUTE'),'account-free class entry remains unavailable');
