INSERT INTO firstten_policy_test.class_results SELECT 'created',public.create_class(firstten_policy_test.id('class_a'),'fc010000-0000-4000-8000-000000000011',(SELECT document FROM firstten_policy_test.class_documents WHERE label='a'));
