SELECT is((SELECT result#>>'{data,role}' FROM firstten_policy_test.class_results WHERE label='created'),'owner','ownership derived from verified actor');
SELECT is((SELECT result#>>'{data,aiEnabled}' FROM firstten_policy_test.class_results WHERE label='created'),'false','class AI starts disabled');
SELECT is(public.create_class(firstten_policy_test.id('class_a'),'fc010000-0000-4000-8000-000000000011',(SELECT document FROM firstten_policy_test.class_documents WHERE label='a')),(SELECT result FROM firstten_policy_test.class_results WHERE label='created'),'create retry returns original acknowledgement');
SELECT is(public.create_class(firstten_policy_test.id('class_a'),'fc010000-0000-4000-8000-000000000011',(SELECT document||'{"name":"Different"}' FROM firstten_policy_test.class_documents WHERE label='a'))->>'code','IDEMPOTENCY_CONFLICT','same create request cannot change class identity/body');
